import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';
import { createNode as _ } from '@/primitives';
import { createText as __ } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, Vector3 } = ctx.THREE;

  const root = new Group();
  const tiles = [];
  const materials = [];
  const texts = [];

  // Gradient colors
  const gradStart = color('#1a1a22');
  const gradEnd = color('#121218');

  // Base geometry for a tile
  const tileGeo = new PlaneGeometry(1, 0.62);

  // Resolve text items
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Separate kicker (first item) from brand marks
  const kickerItem = items[0] ?? null;
  const brandItems = items.slice(1);

  // Grid configuration
  const cols = 3;
  const rows = 2;
  const gap = 0.25;
  const tileW = 1;
  const tileH = 0.62;

  const totalW = cols * tileW + (cols - 1) * gap;
  const totalH = rows * tileH + (rows - 1) * gap;

  const startX = -totalW / 2 + tileW / 2;
  const startY = totalH / 2 - tileH / 2;

  // Helper to set text opacity
  const setTextOpacity = (obj, opacity) => {
    obj.traverse((c) => {
      if (c.isMesh && c.material) {
        c.material.transparent = true;
        c.material.opacity = opacity;
      }
    });
  };

  // Create tiles with brand wordmarks
  brandItems.forEach((item, idx) => {
    const col = idx % cols;
    const row = Math.floor(idx / cols);

    const x = startX + col * (tileW + gap);
    const y = startY - row * (tileH + gap);
    const z = 0;

    // Material per tile
    const mat = new MeshStandardNodeMaterial();
    mat.metalness = 0.5;
    mat.roughness = 0.55;
    mat.clearcoat = 0.2;
    mat.anisotropy = 0.6;
    mat.transparent = true;
    mat.opacity = 0; // start invisible for stagger animation
    mat.colorNode = mix(gradStart, gradEnd, uv().y);

    const tile = new Mesh(tileGeo, mat);
    tile.position.set(x, y, z);
    root.add(tile);

    // Brand wordmark text
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: item.typography?.fontSize ?? 13,
      color: '#e8ecf2',
      align: 'center',
    });
    txt.position.set(0, 0, 0.01);
    setTextOpacity(txt, 0.78);
    tile.add(txt);

    // Store references
    tiles.push(tile);
    materials.push(mat);
    texts.push(txt);

    // Hover handlers
    tile.userData.handlers = {
      hoverEnter: () => {
        gsap.to(tile.position, {
          z: 0.05,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });
        gsap.to(mat, {
          opacity: 1,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });
        setTextOpacity(txt, 1);
      },
      hoverLeave: () => {
        gsap.to(tile.position, {
          z: 0,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });
        gsap.to(mat, {
          opacity: 0.78,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });
        setTextOpacity(txt, 0.78);
      },
    };
  });

  // Kicker text above the grid
  if (kickerItem) {
    const kicker = ctx.fontAtlas.createText(kickerItem.text ?? '', {
      fontSize: kickerItem.typography?.fontSize ?? 9,
      color: '#e8ecf2',
      align: 'center',
    });
    const kickerY = startY + tileH / 2 + 0.3;
    kicker.position.set(0, kickerY, 0.01);
    setTextOpacity(kicker, 1);
    root.add(kicker);
    texts.push(kicker);
  }

  // Staggered entrance animation
  const mountTl = gsap.timeline();
  tiles.forEach((tile, i) => {
    mountTl.from(
      tile.position,
      {
        y: '+=0.2',
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      },
      i * 0.08
    );
    mountTl.from(
      tile.material,
      {
        opacity: 0,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      },
      i * 0.08
    );
  });

  // Cleanup
  root.userData.cleanup = () => {
    mountTl.kill();
    tiles.forEach((t) => {
      t.geometry.dispose();
      t.material.dispose();
    });
    tileGeo.dispose();
    texts.forEach((t) => {
      t.traverse((c) => {
        if (c.isMesh) {
          if (c.geometry) c.geometry.dispose();
          if (c.material) c.material.dispose();
        }
      });
    });
  };

  // Empty handlers container for the root object
  root.userData.handlers = {};

  return root;
}
